package com.rescuefarm.service.seller;
import com.rescuefarm.domain.model.Order;import java.util.*;
public final class SellerDashboardSnapshot{private final int products,activeProducts,campaigns,activeCampaigns,mobileCampaigns,posts,pendingPosts,orders,pendingOrders,deliveryOrders,promotions;private final double revenue,rescuedQuantity;private final List<Order> recentOrders;
 public SellerDashboardSnapshot(int products,int activeProducts,int campaigns,int activeCampaigns,int mobileCampaigns,int posts,int pendingPosts,int orders,int pendingOrders,int deliveryOrders,int promotions,double revenue,double rescuedQuantity,List<Order> recentOrders){this.products=products;this.activeProducts=activeProducts;this.campaigns=campaigns;this.activeCampaigns=activeCampaigns;this.mobileCampaigns=mobileCampaigns;this.posts=posts;this.pendingPosts=pendingPosts;this.orders=orders;this.pendingOrders=pendingOrders;this.deliveryOrders=deliveryOrders;this.promotions=promotions;this.revenue=revenue;this.rescuedQuantity=rescuedQuantity;this.recentOrders=Collections.unmodifiableList(new ArrayList<>(recentOrders));}
 public int getProducts(){return products;}public int getActiveProducts(){return activeProducts;}public int getCampaigns(){return campaigns;}public int getActiveCampaigns(){return activeCampaigns;}public int getMobileCampaigns(){return mobileCampaigns;}public int getPosts(){return posts;}public int getPendingPosts(){return pendingPosts;}public int getOrders(){return orders;}public int getPendingOrders(){return pendingOrders;}public int getDeliveryOrders(){return deliveryOrders;}public int getPromotions(){return promotions;}public double getRevenue(){return revenue;}public double getRescuedQuantity(){return rescuedQuantity;}public List<Order> getRecentOrders(){return recentOrders;}public boolean isEmpty(){return products+campaigns+posts+orders==0;}public boolean hasMoreOrders(){return orders>recentOrders.size();}}
